efault(2.5) // EF: starts at 2.5 per SM-2 spec\n  intervalDays   Int      @default(1) // I: days until next review\n  dueDate        DateTime @default(now()) // Next scheduled review datetime\n\n  // Audit\n  lastReviewedAt DateTime?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  // Relations\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  problem Problem @relation(fields: [problemId], references: [id], onDelete: Cascade)\n\n  // Constraints\n  @@unique([userId, problemId]) // One progress record per user per problem\n  @@index([dueDate]) // Fast backlog queue compilation queries\n  @@index([userId, dueDate]) // Compound index for per-user due queries\n  @@map(\"problem_progresses\")\n}\n\n// ─── Enums ───────────────────────────────────────────────────────────────────\nenum Difficulty {\n  EASY\n  MEDIUM\n  HARD\n}\n\nenum AuthProvider {\n  LOCAL\n  GOOGLE\n  GITHUB\n}\n\n// ─── RefreshToken Model ──────────────────────────────────────────────────────\nmodel RefreshToken {\n  id        String   @id @default(cuid())\n  token     String   @unique // The opaque refresh token string\n  userId    String\n  expiresAt DateTime // 30-day expiry\n  revoked   Boolean  @default(false) // For manual revocation (logout)\n  createdAt DateTime @default(now())\n\n  // Relations\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([expiresAt]) // For cleanup of expired tokens\n  @@map(\"refresh_tokens\")\n}\n",
